

# This file was *autogenerated* from the file 04_kaufman_multiset_AA.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_0 = Integer(0); _sage_const_3 = Integer(3)# cycle 12 / T2→T1: Kaufman の有限 L 閉形式で **2^L 個の固有値全体** を再構成し、
# 実際のスペクトルと AA（実代数的数）上で厳密に一致することを確認する。
#
#   λ = (q(1−q²))^{L/2} · Π_{k=0}^{L−1} ρ(θ_k)^{s_k/2},  s_k = ±1
#   ρ(θ) = coshγ(θ) + sqrt(coshγ(θ)² − 1),  coshγ(θ) = C(q) − cosθ,  C(q)=(1+q²)²/(2q(1−q²))
#   cosθ = (ζ_{2L}^e + ζ_{2L}^{-e})/2  （円分体の元。実数の角も三角関数も使わない）
#   セクター: NS は e=2k+1、R は e=2k。各セクターで符号反転数のパリティを固定。
#
# パリティ規約は仮定せず、4 通り（NS 偶/奇 × R 偶/奇）を全部試して、
# **どれが実スペクトルと厳密一致するか**を計算で決める。
#
# 計算量の注意（隠さず記録）: AA での入れ子平方根の厳密比較は L とともに急激に重くなる。
#   L=2,3 は実行できるが、**L=4 は 10 分以上でも終わらなかったので本スクリプトでは実行していない**。
#   L=4 相当の厳密確認は 03（有理関数・円分体上の恒等式）で別経路により実施済み。
#
# 位置づけ: 既知（Kaufman 1949）の閉形式の再現であり、新しい厳密解ではない。

import time

def states(L):
    return [tuple(_sage_const_1  - _sage_const_2 *((i >> j) & _sage_const_1 ) for j in range(L)) for i in range(_sage_const_2 **L)]

def h(s):
    L = len(s)
    return sum(_sage_const_1  for j in range(L) if s[j] != s[(j+_sage_const_1 ) % L])

def v(s, t):
    return sum(_sage_const_1  for j in range(len(s)) if s[j] != t[j])

def transfer_at(L, q):
    S = states(L)
    n = len(S)
    return matrix(QQ, n, n, lambda i, j: q**(h(S[j]) + v(S[i], S[j])))

def sqrt_rho_list(L, q, sector):
    C = (_sage_const_1  + q**_sage_const_2 )**_sage_const_2  / (_sage_const_2 *q*(_sage_const_1  - q**_sage_const_2 ))
    z = QQbar.zeta(_sage_const_2 *L)
    es = [_sage_const_2 *k + _sage_const_1  for k in range(L)] if sector == 'NS' else [_sage_const_2 *k for k in range(L)]
    out = []
    for e in es:
        cg = AA(C) - AA((z**e + z**(-e)) / _sage_const_2 )      # coshγ(θ)
        out.append((cg + (cg**_sage_const_2  - _sage_const_1 ).sqrt()).sqrt())   # ρ^{1/2}
    return out

def kaufman_multiset(L, q, parity_NS, parity_R):
    P = AA(q*(_sage_const_1  - q**_sage_const_2 )).sqrt()**L                  # (q(1−q²))^{L/2}
    out = []
    for sector, parity in [('NS', parity_NS), ('R', parity_R)]:
        sr = sqrt_rho_list(L, q, sector)
        for bits in range(_sage_const_2 **L):
            s = [(bits >> k) & _sage_const_1  for k in range(L)]
            if sum(s) % _sage_const_2  != parity:
                continue
            val = P
            for k in range(L):
                val = val / sr[k] if s[k] else val * sr[k]
            out.append(val)
    return sorted(out)

xc = AA(_sage_const_2 ).sqrt() - _sage_const_1 
lab = {_sage_const_0 : "偶", _sage_const_1 : "奇"}

print("=== Kaufman 有限 L 閉形式による全スペクトル再構成（AA 上の厳密一致）===")
for q in [QQ(_sage_const_1 )/_sage_const_2 , QQ(_sage_const_1 )/_sage_const_3 ]:
    side = "高温側 q > x_c" if q > xc else "低温側 q < x_c"
    print()
    print(f"--- q = {q} ({side}, x_c = √2−1 = {RR(xc)}) ---")
    for L in [_sage_const_2 , _sage_const_3 ]:
        t0 = time.time()
        actual = sorted(AA(QQbar(e).real()) for e in transfer_at(L, q).eigenvalues(extend=True))
        results = []
        for pNS in [_sage_const_0 , _sage_const_1 ]:
            for pR in [_sage_const_0 , _sage_const_1 ]:
                cand = kaufman_multiset(L, q, pNS, pR)
                ok = len(cand) == len(actual) and all(a == b for a, b in zip(actual, cand))
                results.append(((pNS, pR), ok))
        matched = [k for k, ok in results if ok]
        print(f"  L={L} (2^L={_sage_const_2 **L} 個): パリティ全4通りの判定 = "
              f"{[(f'NS{lab[k[_sage_const_0 ]]}/R{lab[k[_sage_const_1 ]]}', ok) for k, ok in results]}")
        if len(matched) == _sage_const_1 :
            print(f"       ⇒ NS セクター符号反転数 {lab[matched[_sage_const_0 ][_sage_const_0 ]]}数 / "
                  f"R セクター {lab[matched[_sage_const_0 ][_sage_const_1 ]]}数 で **厳密一致**（{round(time.time()-t0,_sage_const_1 )}s）")
        else:
            print(f"       ⇒ 一意に定まらず: {matched}")
        print(f"       λ_max = {RR(max(actual))}, minpoly(λ_max) = {QQbar(max(actual)).minpoly()}")

print()
